const SHORT = ['Ela Greens','Body & Beyond',"Sugar's Daddy",'Shippin','DACBY','Luxova','Orbis Lives','bezgoFresh','CLIKD','Caffena Coffee','Road Athena','Washtro','Desi Machines','Koncite','RECEX','Doffair','Alt F Coworking','Indie Stori','Starz AI','My Soul'];
function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const inv = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length + ' rows'); }
if (trk.length < 200) { throw new Error('ABORT: tracker only ' + trk.length + ' rows - truncated'); }

// live, contactable investors
const live = inv.filter(function (r) { return s(r.investor) && s(r.do_not_contact).toLowerCase() !== 'yes'; });

const cols = Object.keys(trk[0] || {});
let cInv = null; const cDeals = [];
for (const c of cols) {
  const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); }
}

// pairs already used: pipeline + tracker
const used = {};
for (const p of pipe) { used[nz(p.startup) + '|' + nz(p.investor)] = true; }
for (const r of trk) {
  const ik = nz(r[cInv]);
  if (!ik) { continue; }
  for (const c of cDeals) {
    for (const d of s(r[c]).split(/[,;\n]/)) { const t = nz(d); if (t.length > 2) { used[t + '|' + ik] = true; } }
  }
}

const out = [];
for (const st of SHORT) {
  const sk = nz(st);
  let free = 0; const sample = [];
  for (const iv of live) {
    const ik = nz(iv.investor);
    let taken = used[sk + '|' + ik];
    if (!taken) {
      for (const k of Object.keys(used)) {
        if (k.indexOf('|' + ik) > 0) { const a = k.split('|')[0]; if (a.length > 3 && sk.length > 3 && (a.indexOf(sk) >= 0 || sk.indexOf(a) >= 0)) { taken = true; break; } }
      }
    }
    if (!taken) { free++; if (sample.length < 5) { sample.push(s(iv.investor)); } }
  }
  out.push({ startup: st, unpaired_investors: free, sample: sample });
}
out.sort(function (a, b) { return a.unpaired_investors - b.unpaired_investors; });
return [{ json: { live_investors: live.length, tracker_rows: trk.length, headroom: out } }];
